pragma solidity ^0.8.20;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title TicTacToe
 * @notice A gas-optimized, secure, non-custodial PvP Tic Tac Toe game.
 * @dev Implements PULL-OVER-PUSH payments, packed storage, and strict game flow.
 *      Players stake ETH, winner takes all. Draws result in refunds.
 */
contract TicTacToe is ReentrancyGuard {
    // ═══════════════════════════════════════════════════════════════
    // ERRORS
    // ═══════════════════════════════════════════════════════════════

    error InvalidStake();
    error GameNotJoinable();
    error NotYourTurn();
    error CellNotEmpty();
    error InvalidCell();
    error GameNotActive();
    error Unauthorized();
    error TimeoutNotReached();
    error NoPendingWithdrawal();
    error TransferFailed();
    error GameFinishedOrCancelled();

    // ═══════════════════════════════════════════════════════════════
    // EVENTS
    // ═══════════════════════════════════════════════════════════════

    event GameCreated(uint256 indexed gameId, address indexed creator, uint256 stake);
    event GameJoined(uint256 indexed gameId, address indexed opponent);
    event MoveMade(uint256 indexed gameId, address indexed player, uint8 cell);
    event GameFinished(uint256 indexed gameId, address indexed winner, uint256 prize);
    event GameDraw(uint256 indexed gameId);
    event GameCancelled(uint256 indexed gameId);
    event Withdrawal(address indexed player, uint256 amount);

    // ═══════════════════════════════════════════════════════════════
    // STATE VARIABLES
    // ═══════════════════════════════════════════════════════════════

    // Constants
    uint32 public constant TURN_TIMEOUT = 1 hours;
    uint256 private constant GAME_ID_START = 1;

    // Enums
    enum GameStatus { NONE, WAITING, ACTIVE, COMPLETED, CANCELLED }

    // Structs - Packed for minimal storage slots (2 slots per game)
    struct Game {
        // Slot 0 (160 + 32 + 8 + 8 + 32 = 240 bits)
        address player1;      // Creator (Moves first as X, value 1)
        uint32 lastAction;    // Timestamp of last interaction
        uint8 status;         // GameStatus
        uint8 movesMade;      // Count moves to detect draw (max 9)
        uint32 board;         // 3x3 grid, 2 bits per cell (18 bits total used)

        // Slot 1 (160 + 96 = 256 bits)
        address player2;      // Opponent (Moves second as O, value 2)
        uint96 stake;         // Wei per player
    }

    /// @notice Stores all game sessions
    mapping(uint256 => Game) public games;

    /// @notice Tracks withdrawable funds (Pull-over-Push)
    mapping(address => uint256) public pendingWithdrawals;

    /// @notice Counter for game IDs
    uint256 public nextGameId;

    // ═══════════════════════════════════════════════════════════════
    // CONSTRUCTOR
    // ═══════════════════════════════════════════════════════════════

    constructor() {
        nextGameId = GAME_ID_START;
    }

    // ═══════════════════════════════════════════════════════════════
    // EXTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Create a new game with a stake.
     * @return gameId The ID of the created game.
     */
    function createGame() external payable returns (uint256 gameId) {
        // Enforce uint96 for tight packing (79 billion ETH limit)
        if (msg.value > uint96(type(uint96).max)) revert InvalidStake();

        gameId = nextGameId;
        unchecked { ++nextGameId; }

        games[gameId] = Game({
            player1: msg.sender,
            lastAction: uint32(block.timestamp),
            status: uint8(GameStatus.WAITING),
            movesMade: 0,
            board: 0,
            player2: address(0),
            stake: uint96(msg.value)
        });

        emit GameCreated(gameId, msg.sender, msg.value);
    }

    /**
     * @notice Join an existing waiting game.
     * @param gameId The ID of the game to join.
     */
    function joinGame(uint256 gameId) external payable {
        Game storage game = games[gameId];

        // Checks
        if (game.status != uint8(GameStatus.WAITING)) revert GameNotJoinable();
        if (msg.value != game.stake) revert InvalidStake();

        // Effects
        game.player2 = msg.sender;
        game.status = uint8(GameStatus.ACTIVE);
        game.lastAction = uint32(block.timestamp);

        emit GameJoined(gameId, msg.sender);
    }

    /**
     * @notice Make a move on the board.
     * @param gameId The ID of the game.
     * @param cellIndex The cell to mark (0-8, row-major).
     */
    function makeMove(uint256 gameId, uint8 cellIndex) external {
        if (cellIndex > 8) revert InvalidCell();

        // Load critical state to stack
        Game storage game = games[gameId];
        uint8 status = game.status;

        if (status != uint8(GameStatus.ACTIVE)) revert GameNotActive();

        uint8 moves = game.movesMade;
        address p1 = game.player1;
        address p2 = game.player2;

        // P1 moves on even counts (0,2,4..), P2 on odd (1,3,5..)
        // Optimization: checking parity of movesMade
        bool isP1Turn = (moves & 1) == 0;
        address currentPlayer = isP1Turn ? p1 : p2;

        if (msg.sender != currentPlayer) revert NotYourTurn();

        // Check if cell is empty (2 bits per cell)
        uint32 board = game.board;
        uint256 shift = cellIndex * 2;
        uint32 cellValue = (board >> shift) & 3; // Mask 0x3

        if (cellValue != 0) revert CellNotEmpty();

        // Apply move: 1 for P1 (X), 2 for P2 (O)
        // No risk of overflow on playerValue (1 or 2)
        uint32 playerValue = isP1Turn ? 1 : 2;
        board |= (playerValue << shift);

        // Update effects
        game.board = board;
        game.lastAction = uint32(block.timestamp);
        // Safe to use unchecked for moves as logic caps at 9
        unchecked { 
            game.movesMade = moves + 1; 
        }

        emit MoveMade(gameId, msg.sender, cellIndex);

        // Check Resolution
        address winner = _checkWin(board);
        if (winner != address(0)) {
            // Map logic winner (1/2) to address
            address winnerAddr = (winner == address(1)) ? p1 : p2;
            _finishGame(gameId, winnerAddr, game.stake, false);
        } else if (moves + 1 == 9) {
            // Draw
            _finishGame(gameId, address(0), game.stake, true);
        }
    }

    /**
     * @notice Cancel a waiting game and retrieve stake.
     * @param gameId The ID of the game.
     */
    function cancelGame(uint256 gameId) external nonReentrant {
        Game storage game = games[gameId];

        if (game.status != uint8(GameStatus.WAITING)) revert GameNotJoinable();
        if (game.player1 != msg.sender) revert Unauthorized();

        game.status = uint8(GameStatus.CANCELLED);
        uint256 stake = game.stake;

        _credit(msg.sender, stake);

        emit GameCancelled(gameId);
    }

    /**
     * @notice Claim victory if opponent timed out.
     * @param gameId The ID of the game.
     */
    function claimTimeout(uint256 gameId) external nonReentrant {
        Game storage game = games[gameId];

        if (game.status != uint8(GameStatus.ACTIVE)) revert GameNotActive();

        // Check timeout
        if (block.timestamp <= uint256(game.lastAction) + TURN_TIMEOUT) revert TimeoutNotReached();

        // Determine whose turn it was
        bool isP1Turn = (game.movesMade & 1) == 0;

        // If it was P1's turn and they timed out, P2 wins. And vice versa.
        address winner = isP1Turn ? game.player2 : game.player1;

        // Only the winner can claim
        if (msg.sender != winner) revert Unauthorized();

        _finishGame(gameId, winner, game.stake, false);
    }

    /**
     * @notice Withdraw accumulated funds (winnings/refunds).
     */
    function withdraw() external nonReentrant {
        uint256 amount = pendingWithdrawals[msg.sender];
        if (amount == 0) revert NoPendingWithdrawal();

        // Checks-Effects-Interactions
        pendingWithdrawals[msg.sender] = 0;

        (bool success, ) = payable(msg.sender).call{value: amount}("");
        if (!success) revert TransferFailed();

        emit Withdrawal(msg.sender, amount);
    }

    // ═══════════════════════════════════════════════════════════════
    // VIEW FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @notice Get board state unpacked.
     * @param gameId The game ID.
     * @return grid Array of 9 uint8s (0=Empty, 1=X, 2=O).
     */
    function getBoard(uint256 gameId) external view returns (uint8[9] memory grid) {
        uint32 board = games[gameId].board;
        // Unchecked loop is safe for fixed iteration count
        for (uint256 i = 0; i < 9;) {
            grid[i] = uint8((board >> (i * 2)) & 3);
            unchecked { ++i; }
        }
    }

    // ═══════════════════════════════════════════════════════════════
    // INTERNAL FUNCTIONS
    // ═══════════════════════════════════════════════════════════════

    /**
     * @dev Resolves game state and credits funds.
     */
    function _finishGame(uint256 gameId, address winner, uint96 stake, bool isDraw) internal {
        Game storage game = games[gameId];
        game.status = uint8(GameStatus.COMPLETED);

        if (isDraw) {
            // Refund both players
            _credit(game.player1, stake);
            _credit(game.player2, stake);
            emit GameDraw(gameId);
        } else {
            // Winner takes all (2 * stake)
            // Cast to uint256 to prevent overflow on multiplication
            uint256 totalPrize = uint256(stake) * 2;
            _credit(winner, totalPrize);
            emit GameFinished(gameId, winner, totalPrize);
        }
    }

    /**
     * @dev Adds amount to pending withdrawals (PULL pattern).
     */
    function _credit(address payee, uint256 amount) internal {
        if (amount > 0) {
            // Safe math is default in 0.8+, but logic guarantees safety
            pendingWithdrawals[payee] += amount;
        }
    }

    /**
     * @dev Checks for win conditions on the packed board.
     * @param board The packed 18-bit board state.
     * @return address(1) if P1 wins, address(2) if P2 wins, address(0) if no win.
     */
    function _checkWin(uint32 board) internal pure returns (address) {
        // Brute force check the 8 winning lines is gas efficient (no loops/memory alloc)
        address winner;

        // Rows
        if ((winner = _checkLine(board, 0, 1, 2)) != address(0)) return winner;
        if ((winner = _checkLine(board, 3, 4, 5)) != address(0)) return winner;
        if ((winner = _checkLine(board, 6, 7, 8)) != address(0)) return winner;

        // Cols
        if ((winner = _checkLine(board, 0, 3, 6)) != address(0)) return winner;
        if ((winner = _checkLine(board, 1, 4, 7)) != address(0)) return winner;
        if ((winner = _checkLine(board, 2, 5, 8)) != address(0)) return winner;

        // Diagonals
        if ((winner = _checkLine(board, 0, 4, 8)) != address(0)) return winner;
        if ((winner = _checkLine(board, 2, 4, 6)) != address(0)) return winner;

        return address(0);
    }

    /**
     * @dev Helper to check if 3 cells match and are not empty.
     */
    function _checkLine(uint32 board, uint8 c1, uint8 c2, uint8 c3) internal pure returns (address) {
        // Extract 2-bit values
        uint32 v1 = (board >> (c1 * 2)) & 3;
        if (v1 == 0) return address(0); // Empty start cell

        uint32 v2 = (board >> (c2 * 2)) & 3;
        if (v1 == v2) {
            uint32 v3 = (board >> (c3 * 2)) & 3;
            if (v2 == v3) {
                // v1 is either 1 (P1) or 2 (P2)
                return (v1 == 1) ? address(1) : address(2);
            }
        }
        return address(0);
    }
}

